use sqlparser::ast::WindowFrame;
use sqlparser::dialect::PostgreSqlDialect;
use sqlparser::parser::Parser;

fn main() {
    // 1. New option serializes with the AST and can be restored.
    let sql = "SELECT sum(x) OVER (ROWS BETWEEN 1 PRECEDING AND 1 FOLLOWING EXCLUDE TIES) FROM t";
    let ast = Parser::parse_sql(&PostgreSqlDialect {}, sql).unwrap();
    let json = serde_json::to_string(&ast).unwrap();
    assert!(json.contains("\"exclude\":\"Ties\""), "json: {json}");
    let restored = serde_json::from_str::<Vec<sqlparser::ast::Statement>>(&json).unwrap();
    assert_eq!(ast, restored);
    assert_eq!(restored[0].to_string(), sql);

    // 2. Old window frame JSON (units/start_bound/end_bound only) still reads.
    let old_json = r#"{"units":"Rows","start_bound":"CurrentRow","end_bound":null}"#;
    let frame: WindowFrame = serde_json::from_str(old_json).unwrap();
    assert_eq!(frame, WindowFrame {
        units: sqlparser::ast::WindowFrameUnits::Rows,
        start_bound: sqlparser::ast::WindowFrameBound::CurrentRow,
        end_bound: None,
        exclude: None,
    });

    // 3. Frames without exclusion keep the old JSON shape.
    let sql = "SELECT sum(x) OVER (ROWS CURRENT ROW) FROM t";
    let ast = Parser::parse_sql(&PostgreSqlDialect {}, sql).unwrap();
    let json = serde_json::to_string(&ast).unwrap();
    assert!(!json.contains("exclude"), "json: {json}");
    let frame_json = serde_json::to_string(&frame).unwrap();
    assert_eq!(
        frame_json,
        r#"{"units":"Rows","start_bound":"CurrentRow","end_bound":null}"#
    );

    // EXCLUDE NO OTHERS is distinguishable after the round-trip.
    let sql = "SELECT sum(x) OVER (ROWS CURRENT ROW EXCLUDE NO OTHERS) FROM t";
    let ast = Parser::parse_sql(&PostgreSqlDialect {}, sql).unwrap();
    let json = serde_json::to_string(&ast).unwrap();
    assert!(json.contains("\"exclude\":\"NoOthers\""), "json: {json}");
    let restored = serde_json::from_str::<Vec<sqlparser::ast::Statement>>(&json).unwrap();
    assert_eq!(ast, restored);

    println!("all serde checks passed");
}

